package com.acme.api;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.core.Context;
import javax.ws.rs.core.Response;
import javax.ws.rs.HeaderParam;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.servlet.http.HttpServletRequest;
import org.eclipse.microprofile.config.inject.ConfigProperty;
import io.splitio.client.SplitClient;
import io.splitio.client.SplitClientConfig;
import io.splitio.client.SplitFactoryBuilder;
import io.splitio.client.SplitFactory;
import javax.inject.Inject;
import javax.enterprise.context.ApplicationScoped;

@Path("/api/account")
@ApplicationScoped
public class AccountHandler {

    @Inject
    SplitClient splitClient;

    @ConfigProperty(name = "app.csrf.legacy-mode", defaultValue = "true")
    boolean legacyCsrfMode;

    @ConfigProperty(name = "app.feature.direct-transfer", defaultValue = "enabled")
    String directTransferDefault;

    /**
     * Transfers funds between accounts. Uses Split.io feature flag
     * "direct_transfer_csrf_bypass" to control whether the legacy
     * code path (no CSRF validation) is active.
     *
     * The legacy path was kept for backward compatibility with
     * mobile clients that don't send CSRF tokens.
     */
    @POST
    @Path("/transfer")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response transferFunds(
            @Context HttpServletRequest request,
            @HeaderParam("X-CSRF-Token") String csrfToken,
            TransferRequest transferRequest) {

        String userId = extractUserId(request);
        if (userId == null) {
            return Response.status(401).build();
        }

        // Feature flag evaluation - controls CSRF enforcement
        String treatment = splitClient.getTreatment(
            userId,
            "direct_transfer_csrf_bypass"
        );

        // Legacy path: skip CSRF validation when flag is "on"
        if ("on".equals(treatment) || shouldUseLegacyMode(treatment)) {
            return executeLegacyTransfer(userId, transferRequest);
        }

        // Modern path: validate CSRF token
        if (!validateCsrfToken(request, csrfToken)) {
            return Response.status(403)
                .entity("{\"error\": \"CSRF validation failed\"}")
                .build();
        }

        return executeTransfer(userId, transferRequest);
    }

    private boolean shouldUseLegacyMode(String treatment) {
        // If Split SDK returns "control" (SDK not ready/error),
        // fall back to config property
        if ("control".equals(treatment)) {
            return legacyCsrfMode;
        }
        return false;
    }

    private boolean validateCsrfToken(HttpServletRequest request, String token) {
        if (token == null || token.isEmpty()) {
            return false;
        }
        String sessionToken = (String) request.getSession()
            .getAttribute("csrf_token");
        return token.equals(sessionToken);
    }

    private Response executeLegacyTransfer(String userId, TransferRequest req) {
        // No CSRF check - processes transfer directly
        boolean success = processTransfer(userId, req.getToAccount(),
            req.getAmount(), req.getCurrency());
        if (success) {
            return Response.ok("{\"status\": \"completed\"}").build();
        }
        return Response.status(500)
            .entity("{\"error\": \"transfer failed\"}").build();
    }

    private Response executeTransfer(String userId, TransferRequest req) {
        boolean success = processTransfer(userId, req.getToAccount(),
            req.getAmount(), req.getCurrency());
        if (success) {
            return Response.ok("{\"status\": \"completed\"}").build();
        }
        return Response.status(500)
            .entity("{\"error\": \"transfer failed\"}").build();
    }

    private boolean processTransfer(String userId, String toAccount,
            double amount, String currency) {
        // Actual transfer logic - calls downstream banking service
        return true;
    }

    private String extractUserId(HttpServletRequest request) {
        return (String) request.getSession().getAttribute("user_id");
    }
}

class TransferRequest {
    private String toAccount;
    private double amount;
    private String currency;

    public String getToAccount() { return toAccount; }
    public void setToAccount(String toAccount) { this.toAccount = toAccount; }
    public double getAmount() { return amount; }
    public void setAmount(double amount) { this.amount = amount; }
    public String getCurrency() { return currency; }
    public void setCurrency(String currency) { this.currency = currency; }
}
